package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class JsonWriter_nullValue_TriageGen2Test {

    @Test
    public void testNullValue_NoDeferredName() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        // Ensure deferredName is null (default state)
        JsonWriter result = writer.nullValue();

        assertEquals("null", out.toString());
        assertSame(writer, result);
    }

    @Test
    public void testNullValue_WithDeferredName_AndSerializeNullsTrue() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.setSerializeNulls(true);

        // Set a deferred name by calling name()
        writer.name("foo");

        // nullValue() should trigger writeDeferredName() if serializeNulls is true
        JsonWriter result = writer.nullValue();

        // Expected: "foo":null
        assertEquals("\"foo\":null", out.toString());
        assertSame(writer, result);
    }

    @Test
    public void testNullValue_WithDeferredName_AndSerializeNullsFalse() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.setSerializeNulls(false);

        // Set a deferred name by calling name()
        writer.name("foo");

        // nullValue() should skip the name and the value because serializeNulls is false
        JsonWriter result = writer.nullValue();

        // Expected: empty string (the name "foo" is dropped)
        assertEquals("", out.toString());
        assertSame(writer, result);
    }

    @Test
    public void testNullValue_WithComplexStructure() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);

        writer.beginObject();
        writer.name("key1");
        writer.value("value1");
        writer.name("key2");
        writer.nullValue();
        writer.endObject();

        // Expected: {"key1":"value1","key2":null}
        assertEquals("{\"key1\":\"value1\",\"key2\":null}", out.toString());
    }
}
